<?php
namespace Tests\Feature;
use App\Models\Currency;
use App\Models\CurrencyExchange;
use App\Models\FinancialAccount;
use App\Models\User;
use App\Services\Accounting\EntityAccountProvisioner;
use Database\Seeders\ChartOfAccountsSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Spatie\Permission\Models\Permission;
use Tests\TestCase;
class CurrencyExchangeTest extends TestCase {
 use RefreshDatabase;
 private function setupAccounts():array{$user=User::factory()->create();Permission::findOrCreate('administration.view','web');Permission::findOrCreate('administration.update','web');$user->givePermissionTo(['administration.view','administration.update']);$this->seed(ChartOfAccountsSeeder::class);$afn=Currency::create(['code'=>'AFN','name'=>'Afghani','is_active'=>true,'is_base'=>true]);$usd=Currency::create(['code'=>'USD','name'=>'US Dollar','is_active'=>true]);$first=FinancialAccount::create(['type'=>'cashbox','name'=>'AFN Cash','currency_id'=>$afn->id,'created_by'=>$user->id]);$second=FinancialAccount::create(['type'=>'bank','name'=>'USD Bank','currency_id'=>$usd->id,'created_by'=>$user->id]);$provision=app(EntityAccountProvisioner::class);$provision->provision('cashbox',$first->id,$first->name,$afn->id);$provision->provision('bank',$second->id,$second->name,$usd->id);return [$user,$first,$second];}
 private function payload($source,$destination):array{return ['exchange_type'=>'internal','exchange_date'=>'2026-10-25','source_account_id'=>$source->id,'destination_account_id'=>$destination->id,'source_amount'=>'7000.0000','applied_rate'=>'0.014285714286','destination_amount'=>'100.0000','description'=>'AFN to USD conversion'];}
 public function test_cross_currency_exchange_creates_two_posted_balanced_journals():void {[$user,$source,$destination]=$this->setupAccounts();$this->actingAs($user)->post(route('finance.exchanges.store'),$this->payload($source,$destination))->assertRedirect(route('finance.exchanges.index'));$exchange=CurrencyExchange::firstOrFail();$this->assertSame('posted',$exchange->sourceJournal->status);$this->assertSame('posted',$exchange->destinationJournal->status);$this->assertNotEquals($exchange->sourceJournal->currency_id,$exchange->destinationJournal->currency_id);foreach([$exchange->sourceJournal,$exchange->destinationJournal] as $journal){$this->assertEquals($journal->lines->sum('debit'),$journal->lines->sum('credit'));$this->assertCount(2,$journal->lines);}}
 public function test_external_sarafi_requires_name_without_a_provider_account():void {[$user,$source,$destination]=$this->setupAccounts();$data=$this->payload($source,$destination);$data['exchange_type']='external';$this->actingAs($user)->post(route('finance.exchanges.store'),$data)->assertSessionHasErrors('provider_name');$data['provider_name']='Walk-in Sarafi';$this->actingAs($user)->post(route('finance.exchanges.store'),$data)->assertRedirect(route('finance.exchanges.index'));$this->assertDatabaseHas('currency_exchanges',['exchange_type'=>'external','provider_name'=>'Walk-in Sarafi']);}
 public function test_exchange_journal_cannot_be_reversed_individually():void {[$user,$source,$destination]=$this->setupAccounts();$this->actingAs($user)->post(route('finance.exchanges.store'),$this->payload($source,$destination))->assertRedirect(route('finance.exchanges.index'));$exchange=CurrencyExchange::firstOrFail();$this->actingAs($user)->post(route('finance.journals.reverse',$exchange->sourceJournal))->assertSessionHasErrors('status');$this->assertDatabaseCount('journal_entries',2);}
 public function test_exchange_rejects_mismatched_received_amount():void {[$user,$source,$destination]=$this->setupAccounts();$data=$this->payload($source,$destination);$data['destination_amount']='110.0000';$this->actingAs($user)->post(route('finance.exchanges.store'),$data)->assertSessionHasErrors('destination_amount');$this->assertDatabaseCount('currency_exchanges',0);$this->assertDatabaseCount('journal_entries',0);}
 public function test_exchange_rejects_same_currency_accounts():void {[$user,$source,$destination]=$this->setupAccounts();$data=$this->payload($source,$destination);$data['destination_account_id']=$source->id;$this->actingAs($user)->post(route('finance.exchanges.store'),$data)->assertSessionHasErrors('destination_account_id');$this->assertDatabaseCount('currency_exchanges',0);}
}
